-- receptionVisible boolean|null Accueil et prestation : Visibilité de la zone d’accueil ;
-- receptionPersonnel string|null Accueil et prestation : Personnel d’accueil (none, trained ou nonTrained) ;
-- receptionHearingEquipments boolean|null Accueil et prestation : Présence d’équipements d’aide à l’audition et à la communication ;
-- receptionHearingEquipmentsType Array<string>|null Accueil et prestation : Types d’équipements (bim, bmp, lsf, lpc, sts ou other) ;
-- receptionPathFlat boolean|null Accueil et prestation : Chemin entre l’entrée principale du bâtiment et l’accueil de l’établissement ;
-- receptionPathElevator boolean|null Accueil et prestation : Ascenseur/élévateur ;
-- receptionPathStairsCount integer|null Accueil et prestation : Nombre de marches ;
-- receptionPathStairsVisibility boolean|null Accueil et prestation : Repérage des marches ou de l’escalier ;
-- receptionPathStairsDirection string|null Accueil et prestation : Sens de circulation de l’escalier (ascending ou descending) ;
